/bin/sh -lc "phrases='You have exactly three boxes labeled red green and blue At the start the red box contains a silver coin the green box contains a brass key and the blue box contains a glass marble Replace each occurrence of COLOR with whichever label is currently on the box that contains the silver coin Follow the instructions below in the order described When all these operations are complete determine which objects each box contains and which labels are visible Do not explain your reasoning or mention the steps'
tr ' ' '\\n' < .shuffled_prompt.txt | sed '/"'^$/d'"' | sort | uniq -c | awk -v p=\""'$phrases" '"'
{c["'$2]=int(($1+3)/4)}
END{
 n=split(p,a," "); for(i=1;i<=n;i++) c[a[i]]--
 for(w in c) if(c[w]) print c[w],w
}'"' | sort -k2,2"

